def slots_since_epoch(today: date) -> int:
    if today < EPOCH:
        return 0
    count = 0
    d = EPOCH
    while d < today:
        if d.weekday() in POST_WEEKDAYS:
            count += 1
        d += timedelta(days=1)
    return count


def build_markup(post: dict):
    if post.get("button"):
        label, url = post["button"]
        return InlineKeyboardMarkup([[InlineKeyboardButton(label, url=url)]])
    return None


async def send_post(bot: Bot, post: dict) -> None:
    caption = f'{post["text"]}\n\n{post["hashtag"]}'
    reply_markup = build_markup(post)
    photo = image_bytes(post["category"])
    await bot.send_photo(
        chat_id=CHANNEL_ID,
        photo=photo,
        caption=caption,
        parse_mode=ParseMode.HTML,
        reply_markup=reply_markup,
    )


async def main() -> None:
    if not BOT_TOKEN:
        raise RuntimeError("Не задан BOT_TOKEN в переменных окружения")

    bot = Bot(token=BOT_TOKEN)
    bulk = os.environ.get("BULK_MODE", "").lower() in ("1", "true", "yes")

    if bulk:
        logger.info(f"BULK_MODE: публикую все {len(POSTS)} постов подряд")
        for i, post in enumerate(POSTS):
            await send_post(bot, post)
            logger.info(f"Опубликован пост №{i} ({post['category']}) в {CHANNEL_ID}")
            if i < len(POSTS) - 1:
                await asyncio.sleep(3)
        logger.info("Массовая публикация завершена")
        return

    today = date.today()
    force = os.environ.get("FORCE_POST", "").lower() in ("1", "true", "yes")
    if not force and today.weekday() not in POST_WEEKDAYS:
        logger.info("Сегодня не день публикации — выхожу без действий")
        return

    index = slots_since_epoch(today) % len(POSTS)
    post = POSTS[index]
    await send_post(bot, post)
    logger.info(f"Опубликован пост №{index} ({post['category']}) в {CHANNEL_ID}")


if __name__ == "__main__":
    asyncio.run(main())
